dtsPropsFor.Dialog:
/**
 * Compose with DialogTrigger, DialogPortal, DialogOverlay, DialogContent,
 * DialogHeader, DialogTitle, DialogDescription, DialogFooter, DialogClose
 * (all exported from the same bundle).
 */
children?: React.ReactNode;
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/**
 * When true, interaction with outside elements is disabled and only the
 * dialog content is visible to screen readers.
 * @defaultValue true
 */
modal?: boolean;

dtsPropsFor.AlertDialog:
/**
 * Confirmation dialog for irreversible / hard-to-undo actions. Always
 * modal (unlike Dialog, `modal` cannot be turned off). Compose with
 * AlertDialogTrigger, AlertDialogContent, AlertDialogHeader,
 * AlertDialogTitle, AlertDialogDescription, AlertDialogFooter,
 * AlertDialogCancel, AlertDialogAction (all exported from the same
 * bundle).
 */
children?: React.ReactNode;
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;

dtsPropsFor.Popover:
/**
 * Compose with PopoverAnchor, PopoverTrigger, PopoverContent (all
 * exported from the same bundle).
 */
children?: React.ReactNode;
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/**
 * When true, interaction with outside elements is disabled while open.
 * @defaultValue false
 */
modal?: boolean;

dtsPropsFor.Tooltip:
/**
 * Already wraps its subtree in an internal TooltipProvider (delayDuration
 * 200ms) — an explicit outer TooltipProvider is only needed when several
 * tooltips must share hover-skip timing. Compose with TooltipTrigger,
 * TooltipContent (all exported from the same bundle).
 */
children?: React.ReactNode;
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/**
 * Overrides the Provider's delayDuration for this tooltip only.
 * @defaultValue 700
 */
delayDuration?: number;
/**
 * When true, moving the pointer onto the content itself does not keep
 * the tooltip open.
 * @defaultValue false
 */
disableHoverableContent?: boolean;

dtsPropsFor.DropdownMenu:
/**
 * Compose with DropdownMenuTrigger, DropdownMenuContent, DropdownMenuGroup,
 * DropdownMenuLabel, DropdownMenuItem, DropdownMenuCheckboxItem,
 * DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuSeparator,
 * DropdownMenuShortcut, DropdownMenuSub, DropdownMenuSubTrigger,
 * DropdownMenuSubContent (all exported from the same bundle).
 */
children?: React.ReactNode;
dir?: 'ltr' | 'rtl';
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/**
 * When true (default), interaction with outside elements is disabled.
 * @defaultValue true
 */
modal?: boolean;

dtsPropsFor.Alert:
