dtsPropsFor.Sheet:
/** Controlled open state. */
open?: boolean;
/** Uncontrolled initial open state. */
defaultOpen?: boolean;
onOpenChange?: (open: boolean) => void;
/** Whether interaction outside the sheet is disabled while open. @default true */
modal?: boolean;
/**
 * Slide-in panel (built on Radix Dialog). Compose with SheetTrigger,
